"""Condition expression types and evaluators for skill primitives.

Conditions in skill YAML are plain expression strings, e.g.::

    "session.project.authenticated"
    "not session.card_replace.replacement_reason"
    "session.transfer_money.amount == 100"
    "session.skill_a.flag and not session.skill_b.flag"

The single canonical form is the chained, fully-namespaced
``session.{namespace}.{entry_name}`` — where ``{namespace}`` is a skill id, the
``project`` scope, or the ``system`` scope.  ``session.transfer_money.amount``
resolves to the fully-qualified slot name ``"transfer_money.amount"`` in the
memory-values dict produced by
:meth:`~rasa.mantle.memory.manager.MemoryManager.read_all`.

The legacy bare forms — one-level ``session.entry`` and bare ``entry`` without a
``session.`` prefix — are **not** supported: everything is namespaced, so a
condition must always name its scope.
"""

from __future__ import annotations

import ast
from collections.abc import Mapping
from typing import Any

from pydantic import BaseModel, ConfigDict, Field, field_validator

# ---------------------------------------------------------------------------
# Type alias
# ---------------------------------------------------------------------------

Condition = str
"""A plain expression string evaluated against memory values at runtime."""


# Author-facing ``tool_constraints`` / ``requires_confirmation`` field names.
REQUIRES_FIELD = "requires"
PRECONDITION_FIELD = "precondition"
REQUIRES_CONFIRMATION_FIELD = "requires_confirmation"
ON_SUCCESS_FIELD = "on_success"
ON_FAILURE_FIELD = "on_failure"
ENABLED_FIELD = "enabled"
UTTER_FOR_CONFIRMATION_FIELD = "utter_for_confirmation"
UTTER_ON_USER_DENIAL_FIELD = "utter_on_user_denial"

TOOL_CONSTRAINT_FIELDS: tuple[str, ...] = (
    REQUIRES_FIELD,
    REQUIRES_CONFIRMATION_FIELD,
    ON_SUCCESS_FIELD,
    ON_FAILURE_FIELD,
)
TOOL_CONSTRAINT_STRING_FIELDS: tuple[str, ...] = (
    REQUIRES_FIELD,
    ON_SUCCESS_FIELD,
    ON_FAILURE_FIELD,
)
REQUIRES_CONFIRMATION_FIELDS: tuple[str, ...] = (
    ENABLED_FIELD,
    UTTER_FOR_CONFIRMATION_FIELD,
    UTTER_ON_USER_DENIAL_FIELD,
)

# Author-facing skill ``utter:`` trigger field names.
UTTER_ON_FIELD = "on"
UTTER_WHEN_FIELD = "when"
UTTER_ON_ACTIVATE_VALUE = "activate"


# ---------------------------------------------------------------------------
# Pydantic types
# ---------------------------------------------------------------------------


class RequiresConfirmation(BaseModel):
    """Confirmation gate settings for a tool under ``tool_constraints``.

    ``enabled`` turns the confirmation pause on (default ``False``). When
    enabled, the gate pauses before the builder tool runs and resumes only via
    ``resolve_tool_confirmation``. ``utter_for_confirmation`` and
    ``utter_on_user_denial`` are optional names of responses in
    ``responses.yml``. When a name is omitted, the LLM handles that response.
    When supplied, train validation requires the name to exist with a non-empty
    body; the confirmation gate resolves and emits it at pause or decline time.
    Placeholders in the referenced response bodies may use bare entry names
    (``{selected_card_label}``) or fully qualified session paths
    (``{session.card_disambiguation.selected_card_label}``); both resolve via
    :class:`~rasa.mantle.memory.manager.MemoryManager`.
    """

    model_config = ConfigDict(frozen=True, extra="forbid")

    enabled: bool = False
    utter_for_confirmation: str | None = None
    utter_on_user_denial: str | None = None


def is_confirmation_gate_active(
    confirmation: RequiresConfirmation | None,
) -> bool:
    """Return whether a tool should pause for confirmation.

    Frontmatter compilation stores ``None`` when ``enabled`` is false. Flow
    ``tools:`` parsing and direct model construction may still carry a
    ``RequiresConfirmation`` with ``enabled=False``; callers must treat that
    the same as unset so irreversible tools are not paused.
    """
    return confirmation is not None and confirmation.enabled


class GatedTool(BaseModel):
    """A tool with optional availability, confirmation, and outcome triggers.

    ``requires`` gates when the tool may run. ``requires_confirmation`` is set
    when confirmation is enabled (``enabled: true``); nested
    ``utter_for_confirmation`` / ``utter_on_user_denial`` are optional
    ``responses.yml`` response names (omitted names leave that response to the
    LLM). ``on_success`` / ``on_failure`` name verbatim responses in
    ``responses.yml``. Response-name fields are parsed and validated at train
    time. Placeholders in referenced response bodies may use bare entry names
    (``{selected_card_label}``) or fully qualified session paths
    (``{session.card_disambiguation.selected_card_label}``); both resolve via
    :class:`~rasa.mantle.memory.manager.MemoryManager`.
    :class:`~rasa.mantle.orchestration.verbatim_triggers.VerbatimTriggerEvaluator`
    emits outcome fields after the builder tool result. The confirmation gate
    does not read these outcome fields.
    """

    model_config = ConfigDict(frozen=True)

    name: str
    requires: Condition | None = None
    requires_confirmation: RequiresConfirmation | None = None
    on_success: str | None = None
    on_failure: str | None = None

    @field_validator("requires_confirmation", mode="before")
    @classmethod
    def _drop_disabled_confirmation(cls, value: Any) -> Any:
        """Treat ``enabled: false`` / empty mapping like an absent gate."""
        if value is None:
            return None
        if isinstance(value, RequiresConfirmation):
            return value if value.enabled else None
        if isinstance(value, Mapping):
            if value.get(ENABLED_FIELD) is not True:
                return None
            return value
        return value


class VerbatimTrigger(BaseModel):
    """A verbatim response trigger from skill frontmatter ``utter:``.

    At least one of ``on_activate`` or ``when_condition`` must be set; both may be
    set on the same entry. ``on_activate`` fires when the owning skill is activated;
    ``when_condition`` is a :data:`Condition` expression evaluated after memory
    writes at runtime, and fires when it first becomes true.
    """

    model_config = ConfigDict(frozen=True)

    response_name: str
    on_activate: bool = False
    when_condition: Condition | None = None


class NextBranch(BaseModel):
    """A conditional branch in a RouteStep.

    ``if_`` is the condition expression; ``None`` means this is the fallback
    (``else``) branch. The first matching branch wins.
    """

    model_config = ConfigDict(frozen=True, populate_by_name=True)

    if_: Condition | None = Field(None, alias="if")
    then: str


# ---------------------------------------------------------------------------
# Expression evaluator
# ---------------------------------------------------------------------------


class ConditionEvaluationError(Exception):
    """Raised when a condition expression cannot be parsed or evaluated."""


class _PartialKey(BaseModel):
    """Intermediate result of resolving the first (namespace) segment of a chain.

    Returned for the first attribute after ``session`` so that a subsequent
    ``visit_Attribute`` call can compose the full slot name ``"{key}.{attr}"``.

    Example — ``session.transfer_money.amount``:
    1. ``visit_Name("session")``        → ``_SessionNamespace``
    2. ``visit_Attribute(.transfer_money)`` → ``_PartialKey(key="transfer_money")``
    3. ``visit_Attribute(.amount)``      → ``_memory_values["transfer_money.amount"]``

    ``__bool__`` is ``False`` so that a not-yet-completed chain (e.g. an
    unqualified ``session.something`` with no second segment) evaluates as falsy
    rather than raising.
    """

    model_config = ConfigDict(frozen=True)

    key: str

    def __bool__(self) -> bool:
        return False


class _SessionNamespace:
    """Provides ``session.<namespace>.<entry>`` attribute access over memory values.

    The first attribute after ``session`` always yields a :class:`_PartialKey`;
    the full namespaced slot name is composed on the second attribute access in
    :meth:`_ExpressionEvaluator.visit_Attribute`. There is no one-level
    ``session.entry`` shortcut — every reference must name its scope.
    """

    def __init__(self, memory_values: dict[str, Any]) -> None:
        self._values = memory_values

    def __getattr__(self, name: str) -> Any:
        return _PartialKey(key=name)


class _ExpressionEvaluator(ast.NodeVisitor):
    """AST-based evaluator for safe condition expressions.

    Supports (must stay aligned with :class:`_ConditionSyntaxValidator`):
    - Attribute access:  ``session.<namespace>.<entry>``
    - Comparisons:       ``==``, ``!=``, ``<``, ``<=``, ``>``, ``>=``
    - Boolean ops:       ``and``, ``or``, ``not``
    - Constants:         strings, numbers, booleans, None
    - Parentheses

    Rejects other names, incomplete ``session`` / ``session.foo``, calls, lists,
    ``in``, ``+``, and similar. Anything outside this set raises
    :exc:`ConditionEvaluationError`.
    """

    def __init__(self, memory_values: dict[str, Any]) -> None:
        self._memory_values = memory_values
        self._session = _SessionNamespace(memory_values)

    def evaluate(self, expr: str) -> bool:
        try:
            tree = ast.parse(expr, mode="eval")
        except SyntaxError as exc:
            raise ConditionEvaluationError(
                f"Invalid condition expression {expr!r}: {exc}"
            ) from exc
        try:
            result = self.visit(tree.body)
        except TypeError as exc:
            # e.g. ordering ops on incompatible runtime types (str >= int).
            raise ConditionEvaluationError(
                f"Condition expression {expr!r} could not be evaluated: {exc}"
            ) from exc
        return bool(result)

    def visit_Expression(self, node: ast.Expression) -> Any:
        return self.visit(node.body)

    def visit_Constant(self, node: ast.Constant) -> Any:
        return node.value

    def visit_Name(self, node: ast.Name) -> Any:
        if node.id == "session":
            return self._session
        raise ConditionEvaluationError(
            f"Unknown name {node.id!r} in condition expression. Memory must be "
            "referenced via the namespaced form "
            "'session.<skill_id|project|system>.<entry_name>'."
        )

    def visit_Attribute(self, node: ast.Attribute) -> Any:
        obj = self.visit(node.value)
        if isinstance(obj, _SessionNamespace):
            # First level (session.<namespace>) — always defer to a _PartialKey
            # so the namespaced slot key is composed on the next attribute.
            return _PartialKey(key=node.attr)
        if isinstance(obj, _PartialKey):
            # Second (or deeper) level: session.<skill_id>.<entry_name>.
            # Compose the full namespaced slot key and resolve it.
            full_key = f"{obj.key}.{node.attr}"
            return self._memory_values.get(full_key)
        raise ConditionEvaluationError(
            f"Unsupported attribute access on {type(obj).__name__!r} in "
            "expression. Only the namespaced form "
            "'session.<skill_id|project|system>.<entry_name>' is supported."
        )

    def visit_BoolOp(self, node: ast.BoolOp) -> Any:
        if isinstance(node.op, ast.And):
            return all(self.visit(v) for v in node.values)
        if isinstance(node.op, ast.Or):
            return any(self.visit(v) for v in node.values)
        raise ConditionEvaluationError(f"Unsupported boolean operator: {node.op!r}")

    def visit_UnaryOp(self, node: ast.UnaryOp) -> Any:
        if isinstance(node.op, ast.Not):
            return not self.visit(node.operand)
        raise ConditionEvaluationError(f"Unsupported unary operator: {node.op!r}")

    def visit_Compare(self, node: ast.Compare) -> Any:
        left = self.visit(node.left)
        for op, comparator in zip(node.ops, node.comparators):
            right = self.visit(comparator)
            if isinstance(op, ast.Eq):
                result = left == right
            elif isinstance(op, ast.NotEq):
                result = left != right
            elif isinstance(op, ast.Lt):
                result = left < right
            elif isinstance(op, ast.LtE):
                result = left <= right
            elif isinstance(op, ast.Gt):
                result = left > right
            elif isinstance(op, ast.GtE):
                result = left >= right
            else:
                raise ConditionEvaluationError(
                    f"Unsupported comparison operator: {op!r}"
                )
            if not result:
                return False
            left = right
        return True

    def generic_visit(self, node: ast.AST) -> Any:
        raise ConditionEvaluationError(
            f"Unsupported expression node {type(node).__name__!r}. "
            "Conditions support: attribute access, comparisons, boolean operators, "
            "and constants."
        )


def evaluate_expression(expr: str, memory_values: dict[str, Any]) -> bool:
    """Evaluate a condition expression string against the current memory values.

    Args:
        expr: A plain expression string, e.g. ``"session.project.authenticated"``
            or ``"session.pay.amount == 100 and not session.pay.declined"``.
        memory_values: Current memory values keyed by memory key.

    Returns:
        ``True`` if the expression evaluates to a truthy value, ``False`` otherwise.

    Raises:
        ConditionEvaluationError: If the expression cannot be parsed or contains
            unsupported constructs.
    """
    return _ExpressionEvaluator(memory_values).evaluate(expr)


def validate_condition_syntax(expr: str) -> None:
    """Check that *expr* parses and uses only supported condition constructs.

    Walks the AST without evaluating against memory, so train-time validation
    accepts valid ordering operators (e.g. ``>=``) even when values are unset.
    Memory references must be the canonical two-level form
    ``session.<namespace>.<entry>``.

    Args:
        expr: A plain condition expression string.

    Raises:
        ConditionEvaluationError: When the expression cannot be parsed or contains
            unsupported constructs.
    """
    try:
        tree = ast.parse(expr, mode="eval")
    except SyntaxError as exc:
        raise ConditionEvaluationError(
            f"Invalid condition expression {expr!r}: {exc}"
        ) from exc
    # Parse only proves valid Python; this enforces engine-specific condition rules.
    _ConditionSyntaxValidator().visit(tree)


class _ConditionSyntaxValidator(ast.NodeVisitor):
    """Reject unsupported AST nodes without evaluating the expression.

    Train-time dry check: same allowlist as :class:`_ExpressionEvaluator`, but
    does not read memory (so unset values do not affect validity).

    Enforces engine-specific condition rules beyond valid Python syntax:

    - Memory only as ``session.<namespace>.<entry>`` (not bare ``session`` /
      ``session.foo`` or other names)
    - Boolean ops: ``and`` / ``or`` only
    - Unary: ``not`` only
    - Comparisons: ``==``, ``!=``, ``<``, ``<=``, ``>``, ``>=`` only
    - Constants allowed; anything else (calls, lists, ``in``, ``+``, …) rejected
    """

    _MEMORY_FORM = (
        "Memory must be referenced via the namespaced form "
        "'session.<skill_id|project|system>.<entry_name>'."
    )

    def visit_Expression(self, node: ast.Expression) -> None:
        self.visit(node.body)

    def visit_Constant(self, node: ast.Constant) -> None:
        return

    def visit_Name(self, node: ast.Name) -> None:
        # Bare ``session`` is incomplete; valid chains are validated as Attribute
        # nodes and do not recurse into this Name.
        if node.id == "session":
            raise ConditionEvaluationError(
                f"Incomplete memory reference 'session'. {self._MEMORY_FORM}"
            )
        raise ConditionEvaluationError(
            f"Unknown name {node.id!r} in condition expression. {self._MEMORY_FORM}"
        )

    def visit_Attribute(self, node: ast.Attribute) -> None:
        # Only the canonical ``session.<namespace>.<entry>`` form is accepted.
        # Do not recurse into children — a one-level ``session.foo`` must fail
        # here rather than being treated as a valid partial chain.
        if _session_memory_key_from_attribute(node) is not None:
            return
        raise ConditionEvaluationError(
            f"Invalid memory reference in condition. {self._MEMORY_FORM}"
        )

    def visit_BoolOp(self, node: ast.BoolOp) -> None:
        if not isinstance(node.op, (ast.And, ast.Or)):
            raise ConditionEvaluationError(f"Unsupported boolean operator: {node.op!r}")
        for value in node.values:
            self.visit(value)

    def visit_UnaryOp(self, node: ast.UnaryOp) -> None:
        if not isinstance(node.op, ast.Not):
            raise ConditionEvaluationError(f"Unsupported unary operator: {node.op!r}")
        self.visit(node.operand)

    def visit_Compare(self, node: ast.Compare) -> None:
        for op in node.ops:
            if not isinstance(
                op, (ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE)
            ):
                raise ConditionEvaluationError(
                    f"Unsupported comparison operator: {op!r}"
                )
        self.visit(node.left)
        for comparator in node.comparators:
            self.visit(comparator)

    def generic_visit(self, node: ast.AST) -> None:
        raise ConditionEvaluationError(
            f"Unsupported expression node {type(node).__name__!r}. "
            "Conditions support: attribute access, comparisons, boolean operators, "
            "and constants."
        )


def extract_memory_keys(expr: str) -> frozenset[str]:
    """Return fully-qualified memory keys referenced via ``session.*`` in *expr*.

    Only the canonical two-level form ``session.<namespace>.<entry>`` is
    recognised (matching :class:`_ExpressionEvaluator`).

    Args:
        expr: A plain condition expression string.

    Returns:
        Memory keys such as ``card_replace.replacement_reason`` or
        ``project.authenticated``.

    Raises:
        ConditionEvaluationError: When *expr* cannot be parsed.
    """
    try:
        tree = ast.parse(expr, mode="eval")
    except SyntaxError as exc:
        raise ConditionEvaluationError(
            f"Invalid condition expression {expr!r}: {exc}"
        ) from exc
    # Needed so train validation can reject if: refs to unreadable /
    # other-skill memory (syntax-OK alone is not enough).
    return _MemoryKeyExtractor().visit(tree)


class _MemoryKeyExtractor(ast.NodeVisitor):
    """Collect ``session.<namespace>.<entry>`` keys from a condition AST."""

    def __init__(self) -> None:
        self._keys: set[str] = set()

    def visit(self, node: ast.AST) -> frozenset[str]:
        super().visit(node)
        return frozenset(self._keys)

    def visit_Attribute(self, node: ast.Attribute) -> None:
        key = _session_memory_key_from_attribute(node)
        if key is not None:
            self._keys.add(key)
        self.generic_visit(node)


def _session_memory_key_from_attribute(node: ast.Attribute) -> str | None:
    """Return the memory key for a ``session.<namespace>.<entry>`` attribute node.

    Shared helper for :class:`_ConditionSyntaxValidator` and
    :class:`_MemoryKeyExtractor`.

    Returns ``namespace.entry`` when *node* is ``session.<namespace>.<entry>``,
    else ``None``. One place defines the canonical memory-reference shape so
    syntax checks and key extraction cannot drift apart.
    """
    if not isinstance(node.value, ast.Attribute):
        return None
    namespace_node = node.value
    if not isinstance(namespace_node.value, ast.Name):
        return None
    if namespace_node.value.id != "session":
        return None
    return f"{namespace_node.attr}.{node.attr}"


def _try_parse_session_reference(expr: str) -> str | None:
    """Return the memory key for a canonical session reference, or ``None``.

    Only two-level references (``session.<namespace>.<entry>``) count. Literals,
    expressions with operators, and invalid syntax return ``None`` so callers
    treat them as non-references (e.g. pass parameter values through unchanged).
    """
    try:
        tree = ast.parse(expr.strip(), mode="eval")
    except SyntaxError:
        # Expected for non-reference strings; do not log — this is the
        # "not a session reference" path, not an authoring error.
        return None
    body = tree.body
    if isinstance(body, ast.Attribute):
        return _session_memory_key_from_attribute(body)
    return None


def resolve_parameter_map(
    parameters: dict[str, Any], memory_values: dict[str, Any]
) -> dict[str, Any]:
    """Resolve ``session.*`` references in a parameter map to memory values.

    Each value that is a canonical ``session.<namespace>.<entry>`` reference is
    replaced with its current memory value (``None`` when unset); all other
    values (literal strings, numbers, booleans) are passed through unchanged.
    """
    resolved: dict[str, Any] = {}
    for name, value in parameters.items():
        if isinstance(value, str):
            key = _try_parse_session_reference(value)
            if key is not None:
                resolved[name] = memory_values.get(key)
                continue
        resolved[name] = value
    return resolved


# ---------------------------------------------------------------------------
# NextBranch helpers
# ---------------------------------------------------------------------------


def parse_next_branches(raw_list: list[dict[str, Any]]) -> list[NextBranch]:
    """Parse a list of raw YAML branch dicts into ``NextBranch`` objects.

    Handles both ``if``/``then`` form and the ``else`` shorthand::

        - if: "session.x == 'foo'"
          then: flow_a
        - else: flow_b   # fallback; if_ will be None
    """
    branches: list[NextBranch] = []
    for raw in raw_list:
        if "else" in raw:
            branches.append(
                NextBranch.model_validate({"if": None, "then": raw["else"]})
            )
        else:
            branches.append(NextBranch.model_validate(raw))
    return branches


def resolve_next(
    branches: list[NextBranch], memory_values: dict[str, Any]
) -> str | None:
    """Return the first matching branch's target flow/step ID.

    Branches are evaluated in order. A branch with ``if_=None`` (else) matches
    unconditionally and is typically placed last. Returns ``None`` if no branch
    matches (i.e. no else branch and no condition was met).
    """
    for branch in branches:
        if branch.if_ is None:
            return branch.then
        if evaluate_expression(branch.if_, memory_values):
            return branch.then
    return None
